import os,json,urllib.request
query="""select jsonb_build_object('columns',(select jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type,'default',column_default)) from information_schema.columns where table_schema='public' and table_name in ('work_tasks','vineyard_external_resources')), 'constraints',(select jsonb_agg(jsonb_build_object('table',c.relname,'definition',pg_get_constraintdef(k.oid))) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('work_tasks','vineyard_external_resources')),'policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname='public' and tablename in ('work_tasks','vineyard_external_resources')), 'triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'trigger',pg_get_triggerdef(t.oid),'body',pg_get_functiondef(t.tgfoid))) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('work_tasks','vineyard_external_resources') and not t.tgisinternal), 'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'body',pg_get_functiondef(p.oid))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and (p.proname ilike '%work_task%' or p.proname ilike '%external_resource%'))) as contract"""
request=urllib.request.Request('https://api.supabase.com/v1/projects/tbafuqwruefgkbyxrxyb/database/query',data=json.dumps({'query':query,'read_only':True}).encode(),headers={'Authorization':'Bearer '+os.environ['SUPABASE_ACCESS_TOKEN'],'Content-Type':'application/json'})
with urllib.request.urlopen(request,timeout=40) as response: result=json.load(response)
print(json.dumps([{'constraints':row.get('contract',{}).get('constraints',[])} for row in result],indent=2))
